let textureLoadRevision=0;
function renderTextureControl(){const custom=state.textureSource==='upload',item=state.textureUpload;$('textureLibraryBtn').setAttribute('aria-pressed',String(!custom));$('textureCustomBtn').setAttribute('aria-pressed',String(custom));$('textureLibraryControl').hidden=custom;$('textureCustomControl').hidden=!custom;$('textureUploadInfo').hidden=!item;for(const id of ['textureLibraryBtn','textureCustomBtn','textureUploadBtn','removeTexture'])$(id).disabled=state.busy;if($('fabric').disabled!==state.busy)$('fabric').disabled=state.busy;$('textureUploadBtn').textContent=item?'更换质感参考图':'＋ 上传质感参考图';if(item){$('textureUploadThumb').src=item.url;$('textureUploadName').textContent=item.file.name;$('textureUploadName').title=item.file.name;$('textureUploadDimensions').textContent=state.texturePattern.naturalWidth+' × '+state.texturePattern.naturalHeight;}else $('textureUploadThumb').removeAttribute('src');}
function chooseTextureSource(source){if(state.busy||!['library','upload'].includes(source))return;textureLoadRevision++;state.textureSource=source;renderTextureControl();updateCount();}
function clearTextureReference(refresh=true){if(state.busy)return;textureLoadRevision++;if(state.textureUpload)URL.revokeObjectURL(state.textureUpload.url);state.textureUpload=null;state.texturePattern=null;state.textureSource='library';$('textureReferenceFile').value='';renderTextureControl();if(refresh){updateCount();toast('已恢复面料库质感设置')}}
async function uploadTextureReference(file){if(state.busy)return toast('请等待当前生成完成');if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)return toast('质感图请使用 10 MB 以内的 JPG、PNG 或 WEBP');const revision=++textureLoadRevision,url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(img.naturalWidth>16000||img.naturalHeight>16000)throw Error('质感图边长不能超过 16000 像素');if(revision!==textureLoadRevision||state.busy){URL.revokeObjectURL(url);return}if(state.textureUpload)URL.revokeObjectURL(state.textureUpload.url);state.textureUpload={file,url};state.texturePattern=img;state.textureSource='upload';renderTextureControl();updateCount();toast('将优先参考此图的织纹、绒感和光泽，保留 A/B 面花型')}catch(e){URL.revokeObjectURL(url);if(revision===textureLoadRevision)toast(e.message||'质感图无法读取，请更换图片')}}
$('textureLibraryBtn').onclick=()=>chooseTextureSource('library');$('textureCustomBtn').onclick=()=>chooseTextureSource('upload');$('textureUploadBtn').onclick=()=>$('textureReferenceFile').click();$('textureReferenceFile').onchange=()=>uploadTextureReference($('textureReferenceFile').files[0]);$('removeTexture').onclick=()=>clearTextureReference();
$('textureUploadBtn').ondragover=e=>{e.preventDefault();if(!state.busy)$('textureUploadBtn').classList.add('drag')};$('textureUploadBtn').ondragleave=()=>$('textureUploadBtn').classList.remove('drag');$('textureUploadBtn').ondrop=e=>{e.preventDefault();$('textureUploadBtn').classList.remove('drag');uploadTextureReference(e.dataTransfer.files[0])};
$('textureZoom').onclick=()=>{if(!state.textureUpload)return;modal('<h2>面料质感参考图</h2><img id="textureModalImage" class="reference-modal-image" alt="上传的面料质感参考图"><p class="subtle">只参考织纹、绒感、光泽与垂感；花型和颜色使用上传的 A/B 面。</p>');$('textureModalImage').src=state.textureUpload.url;};
renderTextureControl();

(() => {
  const select=document.getElementById('fabric');
  const entries=globalThis.beddingFabricLibrary;
  const ids=entries.map(entry=>entry.id);
  const names=entries.map(entry=>entry.name);
  const hints=entries.map(entry=>entry.group+' · '+entry.hint);
  const asset=(id,full=false)=>'/assets/fabrics/'+id+(ids.includes(id)&&!full?'.jpg':'.png');
  const trigger=document.createElement('button');trigger.type='button';trigger.className='fabric-picker-trigger';trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls','fabricPickerPanel');
  select.hidden=true;select.after(trigger);
  const label=select.closest('.texture-choice-field').querySelector('label');label.htmlFor='fabricPickerTrigger';trigger.id=label.htmlFor;
  const panel=document.createElement('div');panel.id='fabricPickerPanel';panel.className='fabric-picker-panel';panel.hidden=true;panel.setAttribute('role','group');panel.setAttribute('aria-label','选择面料质感');document.body.append(panel);
  const preview=document.createElement('div');preview.className='fabric-hover-preview';preview.hidden=true;preview.id='fabricTexturePreview';document.body.append(preview);
  let lastFocus=null;
  function close(){panel.hidden=true;preview.hidden=true;trigger.setAttribute('aria-expanded','false')}
  function place(){const anchor=document.documentElement.dataset.uiScheme==='B'?document.querySelector('.scheme-texture-library'):null;const r=(anchor||trigger).getBoundingClientRect();panel.style.left=Math.max(8,Math.min(r.left,innerWidth-panel.offsetWidth-8))+'px';panel.style.top=Math.max(8,Math.min(r.bottom+6,innerHeight-panel.offsetHeight-8))+'px'}
  function showPreview(id){const i=ids.indexOf(id);if(i<0){preview.hidden=true;return;}preview.replaceChildren();const img=new Image();img.src=asset(id,true);img.alt=names[i]+'质感 AI 摄影示意';const title=document.createElement('strong');title.textContent=names[i];const caption=document.createElement('p');caption.textContent=hints[i];const note=document.createElement('small');note.textContent='AI 质感示例 · 花型和颜色沿用 A/B 面';preview.append(img,title,caption,note);preview.hidden=false;const r=panel.getBoundingClientRect(),width=Math.min(252,innerWidth-16);preview.style.width=width+'px';let left=r.right+10;if(left+width>innerWidth-8)left=r.left-width-10;if(left<8)left=Math.max(8,innerWidth-width-8);preview.style.left=left+'px';preview.style.top=Math.max(8,Math.min(r.top,innerHeight-preview.offsetHeight-8))+'px'}
  function sync(){const current=select.selectedOptions[0];trigger.replaceChildren();const id=select.value;if(ids.includes(id)){const img=new Image();img.src=asset(id);img.alt='';trigger.append(img)}const text=document.createElement('span');text.textContent=current?.textContent||'选择面料质感';const arrow=document.createElement('span');arrow.textContent='⌄';trigger.append(text,arrow);trigger.disabled=select.disabled;
    panel.replaceChildren();const heading=document.createElement('strong');heading.textContent='选择最接近的质感';const help=document.createElement('small');help.textContent='悬停或键盘聚焦可放大 · AI 示例';panel.append(heading,help);const grid=document.createElement('div');grid.className='fabric-swatch-grid';panel.append(grid);
    const available=[...select.options].map(o=>o.value);const list=available.some(v=>ids.includes(v))?['auto',...ids]:available;
    list.forEach(value=>{const i=ids.indexOf(value),button=document.createElement('button');button.type='button';button.className='fabric-swatch';button.dataset.fabric=value;button.setAttribute('aria-pressed',String(value===id));button.disabled=!available.includes(value);const name=i<0?select.querySelector('option[value="'+value+'"]').textContent:names[i];button.setAttribute('aria-label',name+(button.disabled?'（此产品不适用）':''));if(i>=0){const img=new Image();img.src=asset(value);img.alt='';img.loading='lazy';button.append(img)}const caption=document.createElement('span');caption.textContent=name;button.append(caption);button.addEventListener('pointerenter',()=>showPreview(value));button.addEventListener('focus',()=>showPreview(value));button.addEventListener('click',()=>{select.value=value;select.dispatchEvent(new Event('change',{bubbles:true}));sync();close();trigger.focus()});grid.append(button)});
    if(!panel.hidden)place();
  }
  trigger.addEventListener('click',()=>{if(!panel.hidden)return close();sync();lastFocus=document.activeElement;panel.hidden=false;trigger.setAttribute('aria-expanded','true');place()});
  panel.addEventListener('pointerleave',()=>preview.hidden=true);
  document.addEventListener('pointerdown',e=>{if(!panel.contains(e.target)&&!trigger.contains(e.target))close()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){close();lastFocus?.focus()}});
  document.addEventListener('focusin',e=>{if(!panel.contains(e.target)&&!trigger.contains(e.target))close()});
  window.addEventListener('resize',close);window.addEventListener('scroll',e=>{if(panel.contains(e.target)){preview.hidden=true;return;}close();},true);
  new MutationObserver(()=>{sync();close()}).observe(select,{childList:true,attributes:true,attributeFilter:['disabled']});select.addEventListener('change',sync);sync();
})();
